/**
 * Value selection from a numeric range (`design/components/slider.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/slider.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/slider'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  mergeParts,
  useDirection,
  useMachine,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/slider.module.css'

export interface SliderProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: number | [number, number]
  disabled?: boolean
  /**
   * Formats both the readout and `aria-valuetext`.
   */
  formatValue?: (value: number) => string
  invalid?: boolean
  max?: number
  min?: number
  onChange?: ((value: number) => void) | ((value: [number, number]) => void)
  /**
   * Fires on release. Use it for expensive side effects instead of debouncing `onChange`. Radix
   * commits on pointer release and on each keyboard step, so a blurred slider never holds an
   * uncommitted value.
   */
  onCommit?: ((value: number) => void) | ((value: [number, number]) => void)
  /**
   * Two thumbs on one track. The pair is `[low, high]` and the thumbs cannot cross.
   */
  range?: boolean
  /**
   * Shows the current value at the row's end. Decorative, because the thumb announces it.
   */
  showValue?: boolean
  step?: number
  value?: number | [number, number]
}

/** Value selection from a numeric range. */
export default function Slider(given: SliderProps): JSX.Element {
  const props = mergeProps(
    {
      min: 0,
      max: 100,
      step: 1,
      showValue: false,
      formatValue: String,
      disabled: false,
      invalid: false,
      range: false,
    } as Defaults<
      SliderProps,
      'min' | 'max' | 'step' | 'showValue' | 'formatValue' | 'disabled' | 'invalid' | 'range'
    >,
    claimSlot(given, 'group'),
  )
  const uid = createUniqueId()
  const root = elementRef<HTMLElement>()
  const documentDirection = useDirection(() => root.value)
  const service = useMachine(
    zag.machine,
    () =>
      ({
        id: uid,
        dir: documentDirection(),
        value:
          props.value === undefined
            ? undefined
            : Array.isArray(props.value)
              ? [...props.value]
              : [props.value],
        defaultValue:
          (props.defaultValue === undefined
            ? undefined
            : Array.isArray(props.defaultValue)
              ? [...props.defaultValue]
              : [props.defaultValue]) ?? (props.range ? [props.min, props.min] : [props.min]),
        min: props.min,
        max: props.max,
        step: props.step,
        disabled: props.disabled,
        invalid: props.invalid,
        getAriaValueText: (details) => props.formatValue(details.value),
        onValueChange: (details) => {
          ;(props.onChange as unknown as ((...args: unknown[]) => unknown) | undefined)?.(
            props.range
              ? [details.value[0] ?? props.min, details.value[1] ?? props.min]
              : (details.value[0] ?? props.min),
          )
        },
        onValueChangeEnd: (details) => {
          ;(props.onCommit as unknown as ((...args: unknown[]) => unknown) | undefined)?.(
            props.range
              ? [details.value[0] ?? props.min, details.value[1] ?? props.min]
              : (details.value[0] ?? props.min),
          )
        },
      }) as Partial<zag.Props>,
  )
  const api = createDerived(() => zag.connect(service, normalizeProps))
  const spoken = createDerived(() => api.value.value.map((value) => props.formatValue(value)))
  let release1: (() => void) | undefined
  const effect1 = () => {
    release1?.()
    const ran = agentMember({
      member: 'Slider',
      element: () => root.value?.querySelector('[role="slider"]'),
      state: () => ({
        value: api.value.value[0] ?? props.min,
        high: props.range ? (api.value.value[1] ?? props.min) : null,
        disabled: props.disabled,
        invalid: props.invalid,
      }),
      actions: {
        set: { argument: 'number', run: (value) => api.value.setThumbValue(0, value) },
        'set-high': {
          argument: 'number',
          run: (value) =>
            (() => {
              if (!props.range) throw new Error('A single slider has one value, which set moves.')
              api.value.setThumbValue(1, value)
            })(),
        },
      },
    })
    release1 = () => {
      ran()
    }
  }
  onMount(effect1)
  onCleanup(() => release1?.())
  return (
    <div
      class={styles.root}
      data-disabled={props.disabled ? '' : undefined}
      data-invalid={props.invalid ? '' : undefined}
      data-orientation="horizontal"
      data-member="slider"
      ref={root.attach}
    >
      {props.showValue ? (
        <span class={styles.readout} aria-hidden="true">
          {spoken.value.join('–')}
        </span>
      ) : null}
      {/* control */}
      <div
        {...mergeParts(api.value.getRootProps(), api.value.getControlProps(), {
          class: styles.control,
        })}
      >
        {/* track */}
        <div {...mergeParts(api.value.getTrackProps(), { class: styles.track })}>
          {/* range */}
          <div {...mergeParts(api.value.getRangeProps(), { class: styles.range })} />
        </div>
        <Each of={api.value.value} by={(__thumb, index) => index}>
          {(__thumb, index) => (
            <div
              {...mergeParts(api.value.getThumbProps({ index: index() }), {
                class: styles.thumb,
                'aria-label': props['aria-label'],
                'aria-labelledby': props['aria-labelledby'],
                'aria-describedby': props['aria-describedby'],
                'aria-required': props['aria-required'],
                'aria-invalid': props.invalid ? true : undefined,
                'data-state':
                  Object(api.value.getThumbProps({ index: index() }))['data-dragging'] === ''
                    ? 'dragging'
                    : undefined,
              })}
            />
          )}
        </Each>
      </div>
    </div>
  )
}

Slider.controlKind = 'group'
